log = [
    "10:00 GET /home 200", "10:01 POST /cart 201", "10:02 GET /home 200",
    "10:03 GET /docs 200", "10:04 GET /cart 404", "10:05 GET /docs 200",
    "10:06 GET /home 304", "10:07 DELETE /cart 204", "10:08 GET /about 200",
]

def grep(lines, text):
    return [l for l in lines if text in l]

def cut(lines, sep, field):
    return [l.split(sep)[field - 1] for l in lines]

def sort_lines(lines):
    return sorted(lines)

def uniq_c(lines):
    pairs = []
    for line in lines:
        if pairs and pairs[-1][0] == line:
            pairs[-1][1] += 1
        else:
            pairs.append([line, 1])
    return [tuple(p) for p in pairs]

def head(items, n):
    return items[:n]

counted = uniq_c(sort_lines(cut(grep(log, "GET"), " ", 3)))
for path, count in head(sorted(counted, key=lambda p: -p[1]), 3):
    print(path, count)
